CREATE TABLE IF NOT EXISTS `{PREFIX}debao_webhook_event` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`event_id` varchar(128) NOT NULL,`event_type` varchar(80) NOT NULL,`payload` longtext NOT NULL,`status` varchar(20) NOT NULL DEFAULT 'received',`add_time` int unsigned NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `event_id` (`event_id`)) ENGINE=InnoDB DEFAULT CHARSET={CHARSET};
